(window.RAGHIB = window.RAGHIB || {})["2-10"] = [
  {"a": [267, 267], "h": "\"Spend from the good things you have earned — do not aim for the bad\"", "hAr": "﴿أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ﴾ … ﴿وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ﴾", "said": "الطيب يقال تارة باعتبار الحاسة، وباعتبار العقل تارة، والخبيث في نقيضه، والأظهر أن المعني به هاهنا المعقول الذي هو الحلال ... وحقيقة الطيب من الكسب ما ليس فيه ارتكاب محظور واكتساب محجور، بل منح العقل والشرع تناوله ... وتخصيص المكتسب دون الموروث لأن الإنسان مما يكتسبه أضن منه مما يرثه، فإذا الموروث معقول من فحواه ... إن قيل: لم قال: ﴿وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ﴾ ولم يقل: (ولا تنفقوا الخبيث) مع أن اللفظ كان أوجز؟ قيل: لأن القبيح من الإنسان أن يقصد الخبيث أي الرديء من جملة ما في يده فيخصه بالإنفاق في سبيل الله، فأما إنفاق الرديء لمن ليس له غير ذلك، أو لمن لا يقصده خصوصا فغير مذموم", "en": "\"Good things\" can be good to the senses or good to reason; here the plainer meaning is what reason calls good — the lawful. A good earning is one that involves nothing forbidden, and that reason and the law allow. Earnings are named rather than inheritance because people hold on harder to what they earn than to what they inherit — so inheritance is understood all the more.\n\"Do not aim for the bad of it to spend from\": it was revealed, the report says, when some brought their worst dates as charity. Why \"do not aim for\" and not simply \"do not spend the bad\"? Because what is ugly is to pick out the worst of what you have, on purpose, and set it aside for Allah; one who has nothing better, or gives without singling out the worst, is not blamed. \"And know that Allah is Free of need, Praiseworthy.\"", "ar": "«الطيّب» يُقال باعتبار الحاسّة تارةً وباعتبار العقل تارة، والأظهر أن المعنيّ به هنا المعقول، وهو الحلال؛ وحقيقة الطيّب من الكسب ما ليس فيه ارتكاب محظور، بل أباح العقل والشرع تناوله. وخصّ المكتسب دون الموروث لأن الإنسان بما يكتسبه أضنّ منه بما يرثه، فالموروث معقولٌ من فحواه.\nو﴿وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ﴾: رُوي أنها نزلت حين جاء قومٌ بالحشف من التمر في صدقاتهم. فإن قيل: لِمَ قال «ولا تيمّموا» ولم يقل «ولا تنفقوا الخبيث» وهو أوجز؟ قيل: لأن القبيح أن يقصد الإنسان الرديء من جملة ما في يده فيخصّه بالإنفاق في سبيل الله؛ فأمّا إنفاق الرديء ممّن ليس له غيره، أو ممّن لا يقصده خصوصًا، فغير مذموم.", "links": [{"ref": "3:92", "q": "﴿لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ﴾", "en": "Give from what you love", "ar": "أنفقوا ممّا تحبّون"}, {"ref": "76:8", "q": "﴿وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا﴾", "en": "Feeding others, though they love it", "ar": "يطعمون الطعام على حبّه"}, {"ref": "2:172", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ﴾", "en": "\"Good things\": the lawful", "ar": "الطيّبات: الحلال"}], "v": 1, "p": 562, "pe": 564, "sid": 563},
  {"a": [275, 275], "h": "\"Allah has made trade lawful and forbidden riba\" — why reason itself sees riba as ugly", "hAr": "﴿وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ﴾ — لماذا يستقبح العقلُ الربا", "said": "والربا الزيادة على رأس المال من الربوة على ما تقدم، لكن في تعارف العرب هو لدفع دين بزيادة أو لزيادة ثمن لزيادة في الأجل، وصار في شريعتنا اسما لذلك، ولبيع الأجناس الستة بعضها ببعض متفاضلا ... وقيل: هو تشبيه من لم يفرق بين البيع والربا مع شدة تضادهما وتباين ما بينهما في أن البيع سبب العدل والعمارة للعالم، والربا سبب الجور وخراب العالم فنبه أن قبح الربا مركوز في العقول، بحيث أن من سوى بينه وبين البيع فقد بلغ به الجهل إلى حد الجنون، وقوله: ﴿فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ﴾، أي من انتهى بعد الوعظ، فما أخذه من قبل ملكه، لا اعتراض عليه، ولكن أمره في الآخرة إلى الله", "en": "Riba is increase over the capital. Among the Arabs it meant settling a debt for an increase, or raising the price for more time; in our law it names that, and also trading the six kinds of goods against one another in unequal amounts, and what is joined to them by the same cause.\n\"Those who consume riba will not stand except as one stands whom Satan has struck with madness\": it is said the one who took riba will rise from his grave like a madman. Or it is a likeness for anyone who cannot tell trade from riba, though they are opposites: trade is a cause of fairness and of the world's flourishing; riba is a cause of injustice and of the world's ruin. So the ugliness of riba is planted in reason itself: whoever makes it equal to trade has taken ignorance to the point of madness.\n\"Whoever receives an admonition from his Lord and stops may keep what is past, and his affair is with Allah\": what he took before the admonition is his, not to be contested; his account in the Hereafter is with Allah.", "ar": "«الربا» الزيادة على رأس المال؛ وكان في تعارف العرب لدفع دَينٍ بزيادة، أو لزيادة ثمنٍ لزيادةٍ في الأجل، وصار في شريعتنا اسمًا لذلك، ولبيع الأجناس الستّة بعضها ببعضٍ متفاضلًا، ولما يجري مجراها.\nو﴿لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ﴾: رُوي أن المربي يقوم من قبره يوم القيامة كالمجنون؛ وقيل: هو تشبيهٌ لمن لم يفرّق بين البيع والربا مع شدّة تضادّهما: فالبيع سبب العدل وعمارة العالم، والربا سبب الجور وخراب العالم؛ فنبّه أن قبح الربا مركوزٌ في العقول، حتى إن من سوّى بينه وبين البيع فقد بلغ به الجهل حدّ الجنون.\nو﴿فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ﴾: من انتهى بعد الوعظ فما أخذه من قبلُ ملكه، لا اعتراض عليه، وأمره في الآخرة إلى الله.", "links": [{"ref": "2:276", "q": "﴿يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ﴾", "en": "Riba shrinks, charity grows", "ar": "يمحق الربا ويربي الصدقات"}, {"ref": "2:278", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ﴾", "en": "Leave what remains of it", "ar": "ذروا ما بقي منه"}, {"ref": "2:280", "q": "﴿وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ﴾", "en": "Give the debtor time", "ar": "إنظار المعسر"}], "v": 1, "p": 578, "pe": 578, "sid": 579},
  {"a": [286, 286], "h": "\"Allah does not burden a soul beyond its capacity\" — the prayer that closes the surah", "hAr": "﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ﴾ — الدعاء الذي تُختم به السورة", "said": "بين الله تعالى أنه كلف عبده دون ما تنوء به قدرته ... وقيل: عنى بالكسب ما يفعله الإنسان من فعل خير وجلب نفع من حيثما يجوز إلى غيره، والاكتساب ما يحصله، لنفسه من نفع يجوز تناوله، فنبه أن ما يفعله الإنسان من نفع غيره فله الثواب، وليس عليه فيه الحساب ... قيل: العفو: إزالة الذنب بترك عقوبته، والغفران ستر الذنوب، وكشف الإحسان الذي غطى به، والرحمة إفاضة الإحسان عليه، وقد علم أن الثاني أبلغ من الأول، والثالث أبلغ من الثاني ... فنصرة الله للمؤمنين على وجهين أحدهما: من حيث الحجة، وقد فعل. والثاني: من المداولة التي قال: ﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ﴾ وهذا هو المسؤول أن يجعل لنا عليهم دولة، ولا يجعل لهم علينا دولة ... وهو المشار إليه بقول أمير المؤمنين - رضي الله عنه: \" إن للباطل جولة ثم يضمحل \"", "en": "\"Allah does not burden a soul beyond its capacity\": He has charged His servant with less than would weigh down his strength. \"For it is what it has earned, and against it what it has acquired\": one reading — what a person does to benefit others brings him reward with no reckoning, while what he gains for himself, even lawfully, he will be asked about.\n\"Pardon us, forgive us, have mercy on us\" — each above the one before: pardon removes the sin by leaving its punishment; forgiveness covers it over; mercy pours goodness upon the servant.\n\"Give us victory over the disbelieving people\": Allah has already given the believers victory by proof; what is asked is the other kind — the turns of days that \"We alternate among people\" — that the turn be ours and not theirs. For, as 'Ali said, falsehood has its round, and then it fades away.", "ar": "بيّن الله أنه كلّف عبده دون ما تنوء به قدرته. و﴿لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ﴾: قيل: الكسب ما يفعله الإنسان من خيرٍ ونفعٍ لغيره، والاكتساب ما يحصّله لنفسه من نفعٍ يجوز تناوله؛ فنبّه أن ما يفعله من نفع غيره فله ثوابه وليس عليه فيه حساب، وما يحصّله لنفسه — وإن تناوله من حيث يجوز — فعليه فيه الحساب.\nو﴿وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ﴾: العفو إزالة الذنب بترك عقوبته، والغفران ستر الذنوب، والرحمة إفاضة الإحسان على العبد؛ والثاني أبلغ من الأوّل، والثالث أبلغ من الثاني.\nو﴿أَنتَ مَوۡلَىٰنَا﴾ كقوله ﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ﴾. و﴿فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ﴾: نصرة الله للمؤمنين على وجهين: من حيث الحجّة — وقد فعل —، ومن المداولة التي قال فيها ﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ﴾، وهذا هو المسؤول: أن يجعل لنا عليهم دولةً ولا يجعل لهم علينا دولة؛ وهو المشار إليه بقول أمير المؤمنين عليٍّ: «إن للباطل جولةً ثم يضمحلّ».", "links": [{"ref": "22:78", "q": "﴿وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ﴾", "en": "No hardship in the religion", "ar": "ما جعل عليكم في الدين من حرج"}, {"ref": "3:140", "q": "﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ﴾", "en": "The days in turns", "ar": "الأيام دُوَل"}, {"ref": "21:18", "q": "﴿بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ﴾", "en": "Falsehood has its round, then vanishes", "ar": "للباطل جولةٌ ثم يزهق"}], "v": 1, "p": 599, "pe": 600, "sid": 600}
];
